function language(){return `<div class='language-picker'><button class='language language-trigger' id='language' aria-label='${t('languageTitle')}' aria-haspopup='menu' aria-expanded='false' aria-controls='languageMenu'>${icon('globe')}<span>${{km:'ខ្មែរ',en:'EN',zh:'中文'}[lang]}</span>${icon('chevron','language-chevron')}</button><div class='language-menu' id='languageMenu' role='menu' aria-label='${t('languageTitle')}' hidden><p>${t('languageTitle')}</p>${[['km','ខ្មែរ','Khmer'],['en','English','English'],['zh','中文','Chinese']].map(([code,label,sub])=>`<button role='menuitemradio' aria-checked='${lang===code}' data-language='${code}' lang='${code}'><span><strong>${label}</strong>${label!==sub?`<small>${sub}</small>`:''}</span><span class='language-selected' aria-hidden='true'>${lang===code?'✓':''}</span></button>`).join('')}</div></div>`}
function closeLanguageMenu(focus=false){const menu=$('#languageMenu'),trigger=$('#language');if(menu)menu.hidden=true;trigger?.setAttribute('aria-expanded','false');if(focus)trigger?.focus({preventScroll:true})}
function changeLanguage(value){if(!['en','km','zh'].includes(value))return;const v=$('#player'),state=v?{time:v.currentTime,playing:!v.paused}:null;const y=window.scrollY;lang=value;localStorage.setItem('phsar-language',lang);render();window.scrollTo(0,y);$('#language')?.focus({preventScroll:true});if(state){const next=$('#player');next.addEventListener('loadedmetadata',()=>{next.currentTime=state.time;if(state.playing)playProductVideo()},{once:true})}}
document.addEventListener('click',e=>{const trigger=e.target.closest('#language'),option=e.target.closest('[data-language]');if(trigger){const menu=$('#languageMenu'),open=menu.hidden;menu.hidden=!open;trigger.setAttribute('aria-expanded',String(open));if(open)menu.querySelector('[aria-checked="true"]').focus({preventScroll:true})}else if(option)changeLanguage(option.dataset.language);else if(!e.target.closest('.language-picker'))closeLanguageMenu()});
document.addEventListener('keydown',e=>{if(!e.target.closest('.language-picker'))return;const menu=$('#languageMenu');if(e.key==='Escape'){e.preventDefault();closeLanguageMenu(true)}else if(e.key==='Tab')closeLanguageMenu();else if(['ArrowDown','ArrowUp','Home','End'].includes(e.key)){e.preventDefault();menu.hidden=false;$('#language').setAttribute('aria-expanded','true');const options=[...menu.querySelectorAll('[data-language]')],index=options.indexOf(document.activeElement);const next=e.key==='Home'?0:e.key==='End'?options.length-1:(index+(e.key==='ArrowDown'?1:-1)+options.length)%options.length;options[next].focus()}});

function header(){return `<header class='topbar'>${brand()}<div class='top-actions'>${language()}<button class='icon-button header-cart' data-action='cart' aria-label='${t('cart')}'>${icon('cart')}<span class='cart-count' ${cartCount()?'':'hidden'}>${cartCount()}</span></button></div></header>`}
function nav(){return `<nav class='bottom-nav' aria-label='Main'>${[['home','home','home'],['search','search','searchNav'],['videos','video','videoNav'],['cart','cart','cart'],['profile','user','profile']].map(([a,i,k])=>`<button class='nav-item ${a==='home'&&!activeStore&&!activeCatalog?'active':''}' data-action='${a}' ${a==='search'?`aria-controls='searchOverlay' aria-expanded='false'`:''}>${icon(i)}<span>${t(k)}</span></button>`).join('')}</nav>`}
function heading(title,sub,slider){return `<div class='section-heading'><div><h2>${t(title)}</h2>${sub?`<p>${t(sub)}</p>`:''}</div>${slider?`<div class='slider-arrows'><button class='icon-button' data-slider='${slider}' data-step='-1' aria-label='${t('previous')}'>${icon('back')}</button><button class='icon-button' data-slider='${slider}' data-step='1' aria-label='${t('next')}'>${icon('chevron')}</button></div>`:''}</div>`}
function cardStoreLink(p,cls='product-store-link'){return `<button class='${cls} banner-merchant' data-store='${p.tenantId}' aria-label='${t('visitStore')}: ${esc(productTenant(p).name)}'><span class='merchant-mark'>${icon('store')}</span><span class='card-store-name'>${esc(productTenant(p).name)}</span>${icon('chevron')}</button>`}
function productCard(p){return `<article class='product-card'><button class='product-image' data-product='${p.id}' aria-label='${t('viewProduct')}: ${esc(name(p))}'>${thumbnail(p)}<span class='thumbnail-play'>${icon('play')} ${p.duration}s</span></button><div class='product-caption'><button class='product-name' data-product='${p.id}'>${name(p)}</button>${cardStoreLink(p)}<div class='product-price-row'><strong>${money(p.price)}${rielPrice(p.price)}</strong><button class='small-cart' data-add='${p.id}' aria-label='${t('addCart')}: ${esc(name(p))}'>${icon('cart')}</button></div></div></article>`}
