function categoryMatches(p){return !filter||(filter==='kitchen'?['kitchen','living','groceries'].includes(p.cat):p.cat===filter)}
function homeVideoItems(){const eligible=items.filter(categoryMatches),promoted=eligible.find(p=>p.id===homePromotion.productId),organic=eligible.filter(p=>p.id!==homePromotion.productId);if(!promoted)return eligible.slice(0,12);organic.splice(Math.min(homePromotion.organicBefore,organic.length),0,promoted);return organic.slice(0,12)}
function videoCard(p,sponsored=false){return `<article class='video-card${sponsored?' sponsored-card':''}' data-card='${p.id}'><div class='video-photo'><video data-preview='${p.id}' data-src='${p.video}' poster='${p.poster}' muted playsinline loop preload='none' style='${assetStyle(p)}' aria-label='${esc(name(p))}'></video>${sponsored?`<span class='video-label sponsored-label' aria-label='${t('sponsoredDescription')}'>${t('sponsored')}</span>`:`<span class='video-label'>${icon('video')} ${t(p.hasAudio?'withAudio':'realVideo')}</span>`}<button class='preview-toggle' data-preview-toggle='${p.id}' aria-label='${t('playVideo')}: ${esc(name(p))}'>${icon('play')}</button><button class='video-open' data-product='${p.id}' aria-label='${t('viewProduct')}: ${esc(name(p))}'>${t('viewProduct')}${icon('chevron')}</button><span class='duration'>${p.duration}s</span></div><button class='video-title' data-product='${p.id}'>${name(p)}</button>${cardStoreLink(p,'video-tenant-link')}<div class='video-card-footer'><strong>${money(p.price)}${rielPrice(p.price)}</strong>${sponsored?'':`<span>${t('watchShop')}</span>`}</div></article>`}
function matches(){return items.filter(p=>categoryMatches(p)&&(!query||[...Object.values(p.name),p.id,p.cat].join(' ').toLowerCase().includes(query.toLowerCase())))}
function renderProducts(){return query||filter?renderDiscoveryResults():renderDiscoveryCollections()}

