function renderTenantBanner(p,index){return `<div class='banner-main banner-product banner-tenant banner-campaign-${index}' role='group' aria-label='${index+2} / 4 · ${t('sponsoredDescription')}'><div class='banner-copy'><button class='banner-merchant' data-store='${p.tenantId}' aria-label='${t('visitStore')}: ${esc(productTenant(p).name)}'><span class='merchant-mark'>${icon('store')}</span><span>${esc(productTenant(p).name)}</span>${icon('chevron')}</button><h2>${name(p)}</h2><p class='banner-price'>${money(p.price)}${rielPrice(p.price)}</p><button class='banner-shop' data-product='${p.id}'>${t('viewProduct')}${icon('chevron')}</button></div><img class='banner-product-image' src='${p.poster}' alt='${esc(name(p))}' draggable='false'><span class='banner-ad-label' aria-label='${t('sponsoredDescription')}'>${t('sponsored')}</span></div>`}
